# Where each Vitrail preference lives: one "<file> <key>" per line.
#
# <file> is ~/.config/vitrail/<file>.ini, named after the area of the settings
# window that shows the key. This is the single source of truth: Python
# (vitrail/prefs.py), the bar (bar/prefs.js), the apply script
# (scripts/lib/ini.sh) and the systemd path unit all follow it, and
# tests/test_prefs_map.py checks that every key used anywhere is listed here
# exactly once. A key that is not listed is written to misc.ini.
#
# Keys shared by several pages (radius, blurStrength, surfaceStyle,
# surfaceOpacity) live with the page that owns them: Appearance.

appearance appearance
appearance surfaceStyle
appearance surfaceOpacity
appearance radius
appearance blurStrength
appearance spacing
appearance fontBase
# The shell icon style: an outlined glyph, or the glyph inside a badge.
appearance uiIconFill
# One cursor pack for both themes, or one per theme (see the Cursor tab).
appearance cursorThemeSplit
# A drop grows from the dock icon / launcher row while an app starts.
appearance launchAnimation

colors colorScheme
colors colorContrast

bar barEdge
bar barScreens
bar barStyle
bar barMonitors
# The bar's elements: their order per group, visibility, density and whether a
# fullscreen window hides it. One JSON document (bar/layouts.js).
bar barLayout
# The notification panel's widgets: order, visibility, and the size/style of
# each one. One JSON document (bar/layouts.js, bar/widgets.js).
bar panelLayout
# The desktop widgets: per monitor, each one's point (0..1), size and style.
# One JSON document (bar/layouts.js, bar/widgets.js). With `desktopSync` on,
# every monitor draws the document's `shared` list.
bar desktopLayout
# Whether every monitor shares one desktop document (on) or each keeps its own.
bar desktopSync
# Whether a right click on the desktop opens its menu (Edit → in-place editor).
bar desktopMenu
# Whether the bar editor reorders rows by dragging; its group selectors and
# arrows remain as the keyboard alternative.
bar barDragReorder
bar barSize
bar barOpacity
bar barOpacityFollow
bar frameStyle
bar frameSize
bar panelSize
bar notificationPosition
bar notificationMax
bar notificationDnd
bar notificationMuteUntil
bar notificationSnooze
bar notificationMuted
bar notificationUrgentApps
bar notificationUrgentBypass
bar notificationSnoozes
bar clipboardMax
bar clipboardPaste
bar clipboardRich
bar clipboardPreview
bar mediaStyle
bar trayStyle
# The chips at the end of the bar: battery (only with a battery) and Bluetooth
# (only with an adapter).
bar barBatteryChip
bar barBluetoothChip
# The bar elements that show only while they have something to say: a JSON
# array of element ids (bar/elements.js).
bar barActiveOnly
bar barKeyboard
bar osdKeys
bar osdKeyTime
bar osdHotZone
bar osdSize
bar osdStep
bar osdBrightnessStep
# The volume bar element: the wheel step, the level as text, and whether
# paused streams are left out of its popup.
bar volumeStep
bar volumePercent
bar volumeHideSilent
# The updates bar element: how often it checks (minutes), which sources, and
# the AUR helper ("auto" follows what is installed).
bar updatesInterval
bar updatesSources
bar updatesAurHelper
# The disks bar element: whether a newly plugged drive is mounted on its own,
# and the labels or UUIDs it leaves alone (one JSON array).
bar disksAutomount
bar disksIgnore
# The containers bar element: the engine to use ("auto" follows docker, then
# podman) and the containers pinned first in the popup (one JSON array of names).
bar containersEngine
bar containersPinned
# The peripherals battery element: the device kinds it leaves out (one JSON
# array) and the percentage below which the icon warns.
bar peripheralsHide
bar peripheralsLow
# The brightness bar element: the wheel step (percent), the night light's
# switch, colour temperature and schedule (mode plus fixed hours, one JSON
# document; sun mode uses the weather's times).
bar brightnessStep
bar nightLightEnabled
bar nightLightTemperature
bar nightLightSchedule
# The system health bar element: the free space (percent) under which a disk
# is a problem, and the checks that are on (one JSON array).
bar healthDiskThreshold
bar healthChecks
# The privacy bar element: the kinds it watches (one JSON array) and the dot's
# colour (a palette role).
bar privacyWatch
bar privacyDotColor
# The market bar element: the CoinGecko ids (one JSON array), the currency and
# how often to poll (minutes, never below the module's 5-minute cache).
bar marketSymbols
bar marketCurrency
bar marketInterval
# The dashboard clock widgets: the pomodoro's periods and rounds, and the
# timer's default length, in minutes.
bar pomodoroWork
bar pomodoroRest
bar pomodoroCycles
bar timerMinutes

# The dock: whether it is shown, which edge it takes, whether it hides until
# the pointer reaches the edge, whether it is flush or floating, how its icons
# magnify, the pinned apps (one JSON array, in order) and the widgets reserved
# for the next phase (one JSON array).
dock dockEnabled
dock dockEdge
dock dockAutohide
dock dockAttached
# `planet` (distance falloff), `individual` (only the hovered icon) or `none`;
# `scale`/`lift` from before the pair read as planet.
dock dockMagnify
# How many neighbours the planet falloff reaches, and its largest factor.
dock dockMagnifyRange
dock dockMagnifyScale
dock dockPinned
dock dockWidgets

wallpaper wallpaper
wallpaper wallpaperMode
wallpaper wallpaperDir
wallpaper wallpaperType
wallpaper wallpaperSelection
wallpaper wallpaperInterval
wallpaper wallpaperOrder
wallpaper wallpaperImport
wallpaper wallpaperRemove
wallpaper wallpaperSeed
wallpaper wallpaperEffect
# fine | normal | bold: the dot size and the ascii column count.
wallpaper wallpaperEffectDetail
# A fullscreen window pauses the video, the rotation and the visualiser.
wallpaper wallpaperPauseFullscreen
# How a new picture arrives (none | random | ink | outline | fade) and how
# long that animation runs, in milliseconds.
wallpaper wallpaperTransition
wallpaper wallpaperTransitionTime
# Per-output wallpapers, one JSON object keyed by Hyprland output name.
wallpaper wallpaperMonitors
wallpaper systemColor

# Desktop background extras: the audio visualiser over the wallpaper.
background visualiserEnabled
background visualiserVariant
background visualiserHeight

windows windowLayout
windows visibleColumns
windows followFocus
windows wrapFocus
windows borderWidth
windows opacityFocused
windows opacityUnfocused

# The per-monitor overrides, one JSON object keyed by Hyprland output name.
