input keyboardSwitch
input numlockOnStart
input focusFollowsMouse

terminal terminalScheme
terminal terminalPadding
terminal fontSize
terminal tabStyle
terminal tabIcons
terminal tabNumbers

# The fonts, the icon packs and the cursor of the whole session.
fonts fontSystem
fonts fontConsole
fonts uiIcons
fonts iconTheme
# The palette recolours the folder icons; pack keeps the pack's own fill.
fonts iconAdaptive
fonts iconFill
# The Icons page asks for a .zip import or a user-pack removal; apply-settings
# runs it once and clears the key ("<nonce>|path" / "<nonce>|name").
fonts iconImport
fonts iconRemove
# One cursor pack per mode; empty follows `cursorTheme` for both.
fonts cursorTheme
fonts cursorThemeLight
fonts cursorThemeDark
# The Cursor page asks for a .zip import or a user-pack removal, like the icons.
fonts cursorImport
fonts cursorRemove
# The palette tints the chosen pack; monochrome drops the accent ink.
fonts cursorAdaptive
fonts cursorMonochrome
fonts cursorSize
fonts cursorSpinner

# The apps of the volume and microphone cards, and how they behave.
sound soundOutputApps
sound soundInputApps
sound soundFocusApps
sound soundStep

# Screenshots and screen recording.
capture captureDir
capture captureRecordDir
capture captureRecordAudio
capture captureRecordRegion
capture captureAnimation
capture editorTool
capture editorRemember
capture editorOptions
capture captureAi
capture ocrLanguages
capture captureDetect
capture capturePaletteSize
capture translateTarget

launcher launcherEngine
launcher launcherBangs
launcher launcherModes
launcher launcherView
launcher launcherClear

language language
language languageSystem

datetime timezone
datetime ntp

# A request from the Connection page ("wifi-connect:<ssid>") and a counter the
# page raises with each one; scripts/apply-settings.sh acts when the counter
# differs from the last one it ran.
connection connectionRequest
connection connectionSeq
# Whether the bar reads and shows the link's latency and traffic.
connection networkMetrics

misc selftest
misc quickNotes
misc clipboardColors
# What the dashboard's pomodoro and timer remember, end time included, so a
# running session continues after the bar reloads.
misc pomodoroState
misc timerState

# The place and units of the bar's weather (`vitrail/weather.py`).
weather weatherLocation
weather weatherUnits
